import{_ as t,o,c as r,a2 as a}from"./chunks/framework.CpZKh-tG.js";const g=JSON.parse('{"title":"PRD-020 · Launches Calendar — upcoming + historic global launches on /missions","description":"","frontmatter":{},"headers":[],"relativePath":"prd/PRD-020.md","filePath":"prd/PRD-020.md"}'),i={name:"prd/PRD-020.md"};function s(n,e,c,d,l,h){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="prd-020-·-launches-calendar-—-upcoming-historic-global-launches-on-missions" tabindex="-1">PRD-020 · Launches Calendar — upcoming + historic global launches on <code>/missions</code> <a class="header-anchor" href="#prd-020-·-launches-calendar-—-upcoming-historic-global-launches-on-missions" aria-label="Permalink to &quot;PRD-020 · Launches Calendar — upcoming + historic global launches on `/missions`&quot;">​</a></h1><blockquote><p>Status · Accepted (v0.7 ship — closed by RFC-023) Date · 2026-05-19 Owner · Marko Closes into · RFC-023 Slice gate · v0.7 (lands during current dev cycle alongside hotspots work)</p></blockquote><blockquote><p><strong>Why this is a PRD.</strong> Today <code>/missions</code> surfaces only the 37 hand-curated catalogue entries. There is no global view of <em>what&#39;s launching next</em> or <em>what has launched</em> across the broader spaceflight register. This PRD adds that surface: a banner + dedicated <code>/missions/launches</code> route covering both upcoming and historic launches, importance-tiered, hand-overridable, mobile-first. <strong>The architectural commitment that makes this worth a PRD is the data-sourcing posture</strong> — same agency-first discipline already locked by ADR-046 (imagery) and ADR-051 (LEARN links): primary sources direct (NASA / ESA / JAXA / SpaceX / Roscosmos / ISRO / CNSA + GCAT for historic), aggregators (Launch Library 2) only to fill gaps. We&#39;re not building a UI for someone else&#39;s database.</p></blockquote><hr><h2 id="§why" tabindex="-1">§why <a class="header-anchor" href="#§why" aria-label="Permalink to &quot;§why&quot;">​</a></h2><p>Orrery&#39;s mission catalogue is editorial: 37 hand-picked missions that map to our 3D scenes, /fly trajectories, /moon and /mars markers. Deliberately narrow.</p><p>What it doesn&#39;t tell the user:</p><ol><li><strong>&quot;What&#39;s launching this week?&quot;</strong> — the single most common question a casual visitor asks.</li><li><strong>&quot;How many Falcon 9 flights so far in 2026?&quot;</strong> — slice across the broader register.</li><li><strong>&quot;Show me every Soviet R-7 launch in the 60s.&quot;</strong> — historic exploration that frames the catalogue.</li></ol><p><strong>The architectural risk to manage.</strong> A naïve implementation pipes Launch Library 2 (LL2) into the UI and calls it done. LL2 is the de-facto public aggregator (~350 upcoming + historic back to 1957). It&#39;s permissively licensed and fits a build-time snapshot. <strong>But:</strong> LL2 is itself a downstream aggregator (it sources from Jonathan McDowell&#39;s GCAT + Gunter&#39;s Space Page). Building Orrery&#39;s launches surface as a thin UI over LL2 would make us a downstream-of-a-downstream — fragile coupling, no editorial differentiation, and &quot;Orrery is a fancy UI for thespacedevs&quot; is exactly the brand outcome we don&#39;t want.</p><p>The discipline that already keeps Orrery editorially first-party is locked in two ADRs:</p><ul><li><strong>ADR-046 (agency-first imagery).</strong> NASA / ESA / JAXA / agency portals are tried first; Wikimedia + NASA Images API are the fallback library.</li><li><strong>ADR-051 (agency-first LEARN links).</strong> Operator&#39;s own page must be the first intro link; aggregators second; Wikipedia never alone.</li></ul><p>PRD-020 extends the same pattern to launch data:</p><ul><li><strong>Primary sources (agency-direct):</strong> NASA media schedule + press calendar, ESA operations / press, JAXA press calendar, SpaceX upcoming-launches page, Roscosmos / CNSA / ISRO press feeds. Manual where APIs don&#39;t exist (most of them).</li><li><strong>Historic primary source:</strong> <strong>Jonathan McDowell&#39;s GCAT</strong> (<code>planet4589.org/space/gcat</code>) — the actual canonical register that LL2 itself draws from. <strong>Released under CC-BY</strong>, requires citation. We pull GCAT directly, cite McDowell on the calendar page itself + <code>/library</code> + <code>/credits</code>, and bypass LL2 entirely for historic data.</li><li><strong>Aggregator augmentation (gap-fill only):</strong> LL2 covers small commercial / CubeSat / rideshare launches where direct agency sourcing isn&#39;t realistic. Used only where the agency-first chain returns nothing. Always cited.</li><li><strong>Editorial layer:</strong> featured launches get an Orrery-authored one-sentence context, pulling the calendar closer to the hand-curated catalogue&#39;s voice.</li></ul><p>Same architectural posture as the rest of the corpus: language-neutral base data + locale overlays, agency-first attribution chain, fail-closed validation, build-time fetch (ADR-016).</p><hr><h2 id="§audiences" tabindex="-1">§audiences <a class="header-anchor" href="#§audiences" aria-label="Permalink to &quot;§audiences&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Audience</th><th>Why this helps them</th></tr></thead><tbody><tr><td>Casual learner / first-time visitor</td><td>&quot;What&#39;s launching this week?&quot; answered on the <code>/missions</code> banner. Lands on a featured launch with rocket, agency, payload, 3D scene if we have one.</td></tr><tr><td>STEM student</td><td>Slice the historic register: Falcon 9 cumulative count, Saturn V flight history, Soviet R-7 lineage, Long March family per year. Teaching surface.</td></tr><tr><td>Space enthusiast</td><td>Track the upcoming queue with editorial filtering. &quot;Featured&quot; tier = the launches worth watching. Curated overrides catch the heuristic&#39;s misses.</td></tr><tr><td>Educator / journalist</td><td>Cite the calendar with confidence — every row traces to a primary-source provenance chain (agency-direct OR GCAT OR aggregator-of-last-resort), all visible on hover/long-press.</td></tr></tbody></table><hr><h2 id="§what-s-already-shipped-readiness-inventory" tabindex="-1">§what&#39;s already shipped (readiness inventory) <a class="header-anchor" href="#§what-s-already-shipped-readiness-inventory" aria-label="Permalink to &quot;§what&#39;s already shipped (readiness inventory)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Status</th><th>Source</th></tr></thead><tbody><tr><td><code>/missions</code> catalogue grid (37 hand-curated entries)</td><td>shipped</td><td>PRD-004</td></tr><tr><td><code>static/data/missions/index.json</code> manifest (build-time, language-neutral + locale overlays)</td><td>shipped</td><td>ADR-006, ADR-017</td></tr><tr><td><code>static/data/fleet/launcher/*</code> — 23 launch vehicles</td><td>shipped</td><td>PRD-012, ADR-052</td></tr><tr><td>Agency-first image + link provenance pattern, fail-closed validation</td><td>shipped</td><td>ADR-046, ADR-047, ADR-051</td></tr><tr><td>Build-time fetch scripts under <code>scripts/fetch-*.ts</code> + cache layout</td><td>shipped</td><td>ADR-016</td></tr><tr><td><code>wave23/</code> translation toolchain for new UI string sets</td><td>shipped</td><td>ADR-033</td></tr><tr><td>Per-route readiness signals</td><td>shipped</td><td>ADR-056</td></tr><tr><td>Public <code>/credits</code> (image + text provenance) + <code>/library</code> (outbound link inventory)</td><td>shipped</td><td>ADR-047, ADR-051</td></tr></tbody></table><p><strong>Gaps PRD-020 fills:</strong></p><ul><li>No external-launch-register surface plugged into the corpus.</li><li>No multi-source data pipeline with priority ordering (the imagery + link patterns are agency-first; launches will be too).</li><li>No importance-tiering pattern (the closest precedent — PRD-018 image curation — is heading toward auto-tier + override; PRD-020 lands that model in parallel).</li></ul><hr><h2 id="§goal" tabindex="-1">§goal <a class="header-anchor" href="#§goal" aria-label="Permalink to &quot;§goal&quot;">​</a></h2><p>Ship a launches surface on <code>/missions</code>:</p><ol><li><strong>A banner strip on <code>/missions</code></strong> above the catalogue grid showing the next ~3 featured upcoming launches with live-ish T-0 countdown.</li><li><strong>A dedicated <code>/missions/launches</code> route</strong> with hybrid UI: horizontal <strong>month strip</strong> (jump-to-month) + vertical <strong>timeline list</strong> (chronological detail). Two modes: UPCOMING + HISTORIC.</li><li><strong>An importance-tiering layer</strong> — deterministic heuristic + per-launch curated override file (committed, diff-friendly).</li><li><strong>A multi-source data pipeline</strong> that resolves each launch from the highest-available-priority source, records the full provenance chain per entry, validates fail-closed.</li><li><strong>Cross-integration hooks</strong> — fleet launcher pages get &quot;next flight&quot; + &quot;recent flights&quot; widgets reading the same manifests.</li><li><strong>First-class attribution</strong> — GCAT citation surfaced on the calendar page itself, in <code>/credits</code>, and in <code>/library</code> next to existing citations. CC-BY compliance is a ship-gate, not a follow-up.</li></ol><p><strong>v0.1 ship gate</strong> = banner + dedicated route + heuristic + override + multi-source pipeline (agency-direct + GCAT + LL2-fallback) + fleet &quot;next flight&quot; widget + i18n + attribution surfaces complete.</p><p><strong>v0.2</strong> = mission-catalog backlinks + i18n overlays for high-frequency LL2/agency strings.</p><p><strong>v0.3</strong> = post-launch outcome enrichment loop + Orrery-editorial one-sentence overlays on T1 featured launches.</p><hr><h2 id="§user-stories" tabindex="-1">§user stories <a class="header-anchor" href="#§user-stories" aria-label="Permalink to &quot;§user stories&quot;">​</a></h2><p><strong>US-1 — &quot;What&#39;s launching this week?&quot; on <code>/missions</code>.</strong> Casual visitor lands on <code>/missions</code>. Above the catalogue grid: NEXT LAUNCH · Falcon 9 · Starlink Group 10-31 · T-0 in 2d 4h · Cape Canaveral. Tappable → opens the calendar at that entry.</p><p><strong>US-2 — Browse upcoming launches as a calendar.</strong> <code>/missions/launches</code>. Top: month strip (MAY · JUN · JUL · …) with per-month counts. Tap → timeline scrolls. Timeline rows show T-0 countdown, vehicle, payload, agency flag, tier chip (FEATURED gold / nothing / ROUTINE greyed), webcast-live icon. Each row&#39;s source-chip on hover/long-press shows the full provenance chain (e.g. &quot;NASA media schedule → confirmed via LL2&quot;).</p><p><strong>US-3 — Browse historic launches.</strong> Toggle UPCOMING → HISTORIC. Default: last 30 days. Filters: year range (1957 → today), agency, vehicle family, orbital destination, outcome. Every historic row traces to GCAT with optional secondary sources noted. McDowell citation visible at page footer.</p><p><strong>US-4 — Featured tier surfaces editorial picks.</strong> Crewed launches, beyond-LEO / interplanetary / lunar missions, first-flights of new vehicles, and any launch in the curated <code>launches-curation.json</code> <code>featured</code> list get a gold chip + appear in the <code>/missions</code> banner rotation. Routine LEO comsat constellation batches do not. Marko can manually promote or demote any launch.</p><p><strong>US-5 — &quot;Next Falcon 9 flight&quot; on the fleet launcher page.</strong> <code>/fleet/launcher/falcon-9</code> shows a NEXT FLIGHT widget (T-0 + payload + pad) + RECENT FLIGHTS (last ~5 from historic manifest). Cross-link to <code>/missions/launches?vehicle=falcon-9</code>.</p><p><strong>US-6 — Offline shell holds the calendar.</strong> First page load fetches the static manifest. Subsequent loads (offline shell via @vite-pwa) still render. T-0 counters reflect the last build&#39;s snapshot with a &quot;last refreshed Xh ago&quot; stamp visible.</p><p><strong>US-7 — Attribution is visible, not buried.</strong> McDowell / GCAT citation surfaces in THREE places: (a) at the bottom of the calendar page itself in a small CITATIONS strip; (b) on <code>/credits</code> next to existing image-provenance sections; (c) on <code>/library</code> next to existing outbound link citations. Each calendar row also exposes a per-row provenance chip on hover/long-press. CC-BY compliance is enforced by <code>validate-data.ts</code> (fail-closed if the citation strings disappear).</p><p><strong>US-8 — Editor curation loop (auto + override).</strong> Marko reviews a fresh fetch. Promotes a launch → adds its canonical ID to <code>launches-curation.json</code> <code>featured</code> list with a one-line note. Demotes → <code>demoted</code> list. Curation file committed; next build picks up the override.</p><p><strong>US-9 — Multi-source provenance is transparent.</strong> A featured Artemis II launch row shows: PRIMARY: nasa.gov/artemis-2 → CONFIRMED-VIA: GCAT → AUGMENTED-WITH: LL2 (image + webcast link). Each link in the chain is clickable. The pipeline records this chain; the UI surfaces it on hover/long-press; <code>/credits</code> lists every primary source actively in use.</p><p><strong>US-10 — i18n: UI chrome translated, raw data English-only v0.1.</strong> UI chrome (FEATURED / UPCOMING / HISTORIC / &quot;T-0 in 2d 4h&quot; / month names / orbital category labels / agency type labels / status labels) via Paraglide. Source-data strings (mission names, payload descriptions, rocket variant names) stay English for v0.1 — overlays land in v0.2 for recurring high-value strings.</p><hr><h2 id="§must-have-requirements" tabindex="-1">§must-have requirements <a class="header-anchor" href="#§must-have-requirements" aria-label="Permalink to &quot;§must-have requirements&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Requirement</th></tr></thead><tbody><tr><td><strong>M1</strong></td><td><strong>Multi-source data architecture, agency-first.</strong> A <code>LaunchSource</code> provider interface (mirrors <code>VisionProvider</code> from RFC-022) with explicit priority order: (1) <strong>Agency-direct</strong> providers — <code>NasaSource</code>, <code>EsaSource</code>, <code>JaxaSource</code>, <code>SpaceXSource</code>, <code>RoscosmosSource</code>, <code>IsroSource</code>, <code>CnsaSource</code>. Many of these are scraping- or manual-curation-shaped (no clean JSON APIs); pipeline accepts that. (2) <strong>GCAT direct</strong> (<code>GcatSource</code>) — Jonathan McDowell&#39;s canonical historic register at <code>planet4589.org/space/gcat</code>, downloaded as TSV/text catalogs, parsed locally. Primary source for ALL historic data. (3) <strong>Launch Library 2 fallback</strong> (<code>LL2Source</code>) — <code>https://ll.thespacedevs.com/2.3.0/</code>, anonymous tier (15 req/hour). Used ONLY when (1) + (2) return nothing for an upcoming launch entry (typical case: small commercial / rideshare / CubeSat).</td></tr><tr><td><strong>M2</strong></td><td><strong>Build-time fetch only</strong> per ADR-016. New script <code>scripts/fetch-launches.ts</code> orchestrates the providers in priority order. Each provider writes its raw responses to <code>.launches-cache/&lt;provider&gt;/...</code> (gitignored). A merge step consolidates into <code>static/data/launches.json</code> (upcoming) + <code>static/data/launches-historic.json</code> (everything ≤ today) with full <code>provenance_chain</code> per entry.</td></tr><tr><td><strong>M3</strong></td><td><strong>Two-manifest layout.</strong> <code>launches.json</code> holds future launches only (~350 entries). <code>launches-historic.json</code> is the full register paged by decade (1957–1970 / 1971–1980 / … / 2021–2026) for git friendliness — RFC-023 to finalise paging granularity.</td></tr><tr><td><strong>M4</strong></td><td><strong>Importance tier algorithm — heuristic + curated override.</strong> T1 (FEATURED) = crewed OR beyond-LEO (interplanetary / lunar / cislunar / L1/L2 / heliocentric / Mars / Moon / Venus / Jupiter / Saturn) OR first-flight of a vehicle. T2 (NOTABLE) = first flight from a new pad, first reusable-stage milestone, agency-debut. T3 (STANDARD) = everything else. T4 (ROUTINE) = LEO comsat constellation batches (Starlink / OneWeb / Kuiper / Qianfan), GTO comsat, run-of-the-mill resupply. Override file <code>static/data/launches-curation.json</code> (committed, hand-edited) holds <code>featured</code> + <code>demoted</code> lists by launch ID. Pipeline applies overrides AFTER heuristic.</td></tr><tr><td><strong>M5</strong></td><td><strong>Launch manifest schema (per entry).</strong> Required fields: <code>id</code> (Orrery-internal stable slug, e.g. <code>2026-05-26-falcon9-starlink-10-31</code>), <code>net</code> (ISO 8601), <code>net_precision</code>, <code>window_start</code>, <code>window_end</code>, <code>status</code>, <code>name</code>, <code>mission_name</code>, <code>mission_type</code>, <code>orbit_abbrev</code>, <code>orbit_name</code>, <code>agency_id</code>, <code>agency_name</code>, <code>agency_type</code>, <code>country</code>, <code>rocket_config_name</code>, <code>rocket_family</code>, <code>orrery_launcher_ref</code> (fleet launcher id if mapped, else null), <code>pad_name</code>, <code>pad_location</code>, <code>image_url</code>, <code>image_credit</code>, <code>tier</code> (T1–T4), <code>tier_reason</code>, <code>provenance_chain</code> (array of <code>{ source, source_url, fetched_at, role }</code> where <code>role ∈ { &quot;primary&quot;, &quot;confirmed-via&quot;, &quot;augmented-with&quot;, &quot;fallback-primary&quot; }</code>), <code>editorial_note</code> (optional, Orrery-authored one-sentence context for T1 featured), <code>fetched_at</code>.</td></tr><tr><td><strong>M6</strong></td><td><strong>Curation file schema.</strong> <code>static/data/launches-curation.json</code> (committed): <code>{ &quot;version&quot;: 1, &quot;featured&quot;: [{ &quot;launch_id&quot;: &quot;…&quot;, &quot;reason&quot;: &quot;…&quot;, &quot;editorial_note&quot;: &quot;…&quot;, &quot;added_by&quot;: &quot;marko&quot;, &quot;added_at&quot;: &quot;…&quot; }, …], &quot;demoted&quot;: [{ &quot;launch_id&quot;: &quot;…&quot;, &quot;reason&quot;: &quot;…&quot;, … }, …] }</code>. The <code>editorial_note</code> field flows through to the manifest entry (M5) so curated featured launches can carry an Orrery-authored one-sentence framing.</td></tr><tr><td><strong>M7</strong></td><td><strong><code>/missions</code> banner.</strong> New top-of-route component <code>LaunchesBanner.svelte</code>. Shows next 1–3 T1 launches by <code>net</code> ascending. Mobile: single-card swipe. Desktop: 3-card row. Each card: T-0 countdown, vehicle, payload, agency flag, tier chip, editorial note if present. Tap → <code>/missions/launches?id=&lt;launch-id&gt;</code>.</td></tr><tr><td><strong>M8</strong></td><td><strong><code>/missions/launches</code> route.</strong> New route. Layout: filter strip + horizontal month strip + vertical timeline list. UPCOMING / HISTORIC toggle. Filters: agency, vehicle family, orbital destination, outcome (historic only), year range, tier (FEATURED ONLY ↔ ALL). Deep-link friendly URL state via the existing untrack() pattern.</td></tr><tr><td><strong>M9</strong></td><td><strong>Mobile-first.</strong> Designed at 375 px. Banner: single-card swipe → 3-card row at ≥ 768 px. Calendar: timeline + horizontal-scroll month strip on mobile; sidebar filter drawer on filter-button tap. Touch targets ≥ 44×44 px.</td></tr><tr><td><strong>M10</strong></td><td><strong>Cross-integration: fleet launcher pages.</strong> Each <code>/fleet/launcher/&lt;id&gt;</code> gains NEXT FLIGHT + RECENT FLIGHTS sections. Reads launches manifests filtered by <code>orrery_launcher_ref === &lt;id&gt;</code>. Requires <code>ll2-rocket-mapping.json</code> → rename to <code>launches-rocket-mapping.json</code> (since not LL2-specific): a manual map from <code>rocket_family</code> strings to fleet launcher ids covering our 23 launchers. Unmapped vehicles surface in the calendar with <code>orrery_launcher_ref: null</code> — they appear; they just don&#39;t backlink.</td></tr><tr><td><strong>M11</strong></td><td><strong>Refresh cadence per source.</strong> GH Actions cron workflow <code>.github/workflows/refresh-launches.yml</code>: (a) <strong>GCAT</strong> — pulled weekly (its data update cadence is roughly monthly per the release header); pinned to a specific GCAT release version with explicit <code>git diff</code> of the manifest committed. (b) <strong>LL2 augmentation</strong> — every 6 hours (only fetches launches not already resolved by agency-direct or GCAT). (c) <strong>Agency-direct providers</strong> — manual/operator-triggered for v0.1 (a <code>marko bot</code> schedule of weekly review of nasa.gov / esa.int / jaxa.jp / spacex.com / etc. for the upcoming-launches windows). v0.2 graduates the most reliable agency sources (e.g. NASA RSS feeds) to automated cadence. T-0 counters stamp <code>fetched_at</code> per provider; a &quot;last refreshed Xh ago&quot; stamp shows the freshest of the chain.</td></tr><tr><td><strong>M12</strong></td><td><strong>Cache + idempotency.</strong> Each provider&#39;s raw responses cached at <code>.launches-cache/&lt;provider&gt;/...</code>. Merge step idempotent: running twice with no source changes produces a byte-identical manifest. GCAT cache invalidated by GCAT release-version bump. LL2 cache by ETag. Agency-direct providers by content hash of the scraped page.</td></tr><tr><td><strong>M13</strong></td><td><strong>Validation (fail-closed).</strong> <code>validate-data.ts</code> gains new checks: <code>launches.json</code> + <code>launches-historic.json</code> validate against ajv schemas. Every entry must have <code>provenance_chain</code> with at least one <code>{ role: &quot;primary&quot; }</code> OR <code>{ role: &quot;fallback-primary&quot; }</code> entry. Schema malformation = fail. Missing primary provenance = fail. The CITATION strings (GCAT McDowell citation; LL2 attribution where used; any agency citation explicitly required) must be present in <code>static/data/text-sources.json</code> or <code>static/data/source-logos.json</code> per ADR-047 — fail-closed if absent. CC-BY compliance lives at this validation gate, not in operator memory.</td></tr><tr><td><strong>M14</strong></td><td><strong>Attribution surfacing — three places, ship-gate (NOT follow-up).</strong> (a) <strong>On the calendar page itself</strong> (<code>/missions/launches</code>): a CITATIONS strip at the page footer naming Jonathan McDowell / GCAT (CC-BY) + any other primary sources actively used in the current manifest. Links to <code>planet4589.org/space/gcat</code> + agency sources. (b) <strong>On <code>/credits</code></strong>: a new LAUNCH DATA section with the McDowell citation, GCAT release version pinned in the build, the per-source provenance summary (counts of entries by primary source). (c) <strong>On <code>/library</code></strong>: GCAT + each agency-direct source + LL2 added as outbound-link entries with proper provenance per ADR-051 (native-language priority where applicable, <code>rel=&quot;noopener noreferrer external&quot;</code>).</td></tr><tr><td><strong>M15</strong></td><td><strong>i18n.</strong> UI chrome via Paraglide. Source-data strings (mission/payload/vehicle variants) English-only v0.1. Wave23 catalog/maps/apply-translations cycle picks up the new chrome strings. Citation strings themselves stay English (canonical academic-citation form is language-neutral).</td></tr><tr><td><strong>M16</strong></td><td><strong>No client storage.</strong> Per ADR-018 + ADR-057. All filter state URL-encoded.</td></tr><tr><td><strong>M17</strong></td><td><strong>Mission-catalog backlink (v0.1 best-effort, false-positive-NOT-OK).</strong> When a launch matches one of our 37 catalogue missions (agency + vehicle + launch date ± 2 days + best-effort mission name token overlap), surface &quot;→ Open in Orrery&quot; → existing mission detail. False-negatives OK; false-positives must not happen. v0.2 adds a manual <code>orrery_mission_ref</code> lookup for heuristic misses.</td></tr><tr><td><strong>M18</strong></td><td><strong>Status-aware UI.</strong> Map source-provided status into four visual states: SCHEDULED (greys countdown if TBD), GO (countdown live), IN-FLIGHT (live banner), OUTCOME (success/failure/partial badge). Failure rows show source-provided fail reason text with attribution.</td></tr><tr><td><strong>M19</strong></td><td><strong>Performance budget.</strong> <code>launches.json</code> ≤ 250 KB gzipped. <code>launches-historic.json</code> paged per decade, each ≤ 1 MB gzipped, lazy-loaded by year-range filter. First-paint bundle impact at <code>/missions/launches</code>: ≤ 300 KB additional over <code>/missions</code>.</td></tr><tr><td><strong>M20</strong></td><td><strong>Webcast-live signal.</strong> Where source data provides a live-webcast URL (agency stream first, LL2 fallback), surface a LIVE indicator + &quot;watch&quot; link. No embedded video v0.1.</td></tr><tr><td><strong>M21</strong></td><td><strong>GCAT integration mechanics.</strong> GCAT publishes catalogs as fixed-width text + TSV. <code>scripts/gcat-source.ts</code> downloads the <strong>Orbital Launch Log</strong> TSV (the derived catalog of orbital launches + payloads), parses the column-described format per the GCAT documentation, normalises to the M5 schema. GCAT release version (e.g. &quot;1.8.0&quot;) + data-update date are recorded in the manifest header AND committed to <code>text-sources.json</code> for the citation. A GCAT major-version bump (1.x → 2.x) requires a manual review pass before promotion (potential schema change).</td></tr></tbody></table><hr><h2 id="§should-have-requirements" tabindex="-1">§should-have requirements <a class="header-anchor" href="#§should-have-requirements" aria-label="Permalink to &quot;§should-have requirements&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Requirement</th></tr></thead><tbody><tr><td><strong>S1</strong></td><td>&quot;Notify me&quot; placeholder UI on featured launches (mailto: link with pre-filled subject; real notification system out of scope).</td></tr><tr><td><strong>S2</strong></td><td>iCal export per launch (client-side <code>.ics</code> from manifest).</td></tr><tr><td><strong>S3</strong></td><td>Spotlight one historic launch on-this-day in the <code>/missions</code> banner when upcoming queue is thin (≤ 1 T1 in next 48 h).</td></tr><tr><td><strong>S4</strong></td><td>Filter chip presets (&quot;This week&quot; / &quot;Crewed only&quot; / &quot;Beyond LEO&quot; / &quot;First flights&quot;).</td></tr><tr><td><strong>S5</strong></td><td>&quot;Heatmap&quot; historic-mode visualisation: year × agency grid of launch counts, tappable.</td></tr><tr><td><strong>S6</strong></td><td>Per-source toggle on <code>/credits</code> (show only entries whose primary source is NASA, ESA, JAXA, GCAT, LL2, …) — surfaces the multi-source posture concretely.</td></tr></tbody></table><hr><h2 id="§will-not-have-v0-1" tabindex="-1">§will-not-have (v0.1) <a class="header-anchor" href="#§will-not-have-v0-1" aria-label="Permalink to &quot;§will-not-have (v0.1)&quot;">​</a></h2><ul><li><strong>Embedded video webcasts.</strong> Link out only.</li><li><strong>Real push notifications.</strong> Mailto placeholder.</li><li><strong>Editorial mission writeups for every LL2/agency-sourced launch.</strong> That&#39;s what the 37-mission hand-curated catalogue is for. Featured launches optionally carry a one-sentence <code>editorial_note</code> (M6); the rest surface raw source fields.</li><li><strong>i18n overlays for source-data strings.</strong> v0.1 keeps these English.</li><li><strong>Auto-detection of new vehicle families.</strong> Unmapped vehicles surface with <code>orrery_launcher_ref: null</code>; operator catches via audit report, edits the mapping file.</li><li><strong>Roscosmos / CNSA / ISRO full agency-direct integration.</strong> v0.1 falls back to GCAT (historic) + LL2 (upcoming) for these; agency-direct providers added incrementally in v0.2+.</li><li><strong>Capacitor mobile native notification.</strong> Defer to PRD-015 / RFC-018.</li><li><strong>Outcome-write-back to LL2 / GCAT.</strong> Downstream consumer only.</li></ul><hr><h2 id="§success-criteria" tabindex="-1">§success-criteria <a class="header-anchor" href="#§success-criteria" aria-label="Permalink to &quot;§success-criteria&quot;">​</a></h2><p><strong>Editorial:</strong></p><ol><li>≥ 95 % of T1 (FEATURED) launches in the next 90 days are launches Marko + 1 reviewer agree should be featured.</li><li>0 false-positive mission-catalog backlinks (M17).</li><li>Every calendar row&#39;s <code>provenance_chain</code> contains at least one <code>primary</code> or <code>fallback-primary</code> entry. No silent LL2-only rows for launches an agency directly covers.</li><li>McDowell / GCAT citation visible on <code>/missions/launches</code>, <code>/credits</code>, AND <code>/library</code> — verified by a Playwright spec that reads each route + asserts the citation string.</li></ol><p><strong>Technical:</strong> 5. <code>npm run fetch:launches</code> cache-cold completes in ≤ 8 minutes (GCAT TSV parse + agency-direct sweep + LL2 fill). 6. Build-cron refresh workflow stable: 4 consecutive runs land without manual intervention. 7. First-paint bundle impact on <code>/missions/launches</code> ≤ 300 KB additional over <code>/missions</code>. 8. <code>validate-data.ts</code> enforces existing fail-closed gates AND the new launch + curation + citation schemas. 9. Mobile-first works at 375 px without horizontal overflow + all touch targets ≥ 44 px. 10. Offline shell loads the calendar from the last manifest.</p><p><strong>Operational:</strong> 11. Curation loop: editing <code>launches-curation.json</code> + re-running the pipeline applies the override within one build cycle. 12. Adding a new agency-direct provider takes one new <code>&lt;Agency&gt;Source.ts</code> file implementing the <code>LaunchSource</code> interface + one entry in the providers config + an attribution line in <code>text-sources.json</code>. 13. GCAT release-version bump is a one-file change in the build config + a re-run.</p><hr><h2 id="§dependencies" tabindex="-1">§dependencies <a class="header-anchor" href="#§dependencies" aria-label="Permalink to &quot;§dependencies&quot;">​</a></h2><ul><li><strong>ADR-016 (build-time asset resolution)</strong> — strictly respected: zero runtime fetches from the deployed app.</li><li><strong>ADR-046 (agency-first imagery)</strong> — same priority discipline now applied to launch data. PRD-020 cites this ADR as precedent.</li><li><strong>ADR-047 (provenance + license stewardship)</strong> — every primary source registered in <code>text-sources.json</code>; CC-BY compliance enforced by <code>validate-data.ts</code>.</li><li><strong>ADR-051 (LEARN links — agency-first, native-language priority)</strong> — <code>/library</code> integration follows this exact pattern.</li><li><strong>ADR-052 / ADR-053 (fleet schema + imagery)</strong> — <code>orrery_launcher_ref</code> joins from launches into fleet entries. No symmetric-link enforcement (a launcher having upcoming/recent flights is a query result, not stored cross-ref).</li><li><strong>ADR-017 / ADR-033 (i18n)</strong> — new UI string set via <code>wave23/</code>.</li><li><strong>ADR-018 (mobile-first)</strong> — bottom-sheet filter drawer on mobile.</li><li><strong>ADR-056 (e2e readiness signals)</strong> — <code>/missions/launches</code> exposes <code>data-route-ready</code> once manifest is rendered.</li><li><strong>ADR-057 (no client storage)</strong> — all filter state URL-encoded.</li></ul><hr><h2 id="§resolved-decisions" tabindex="-1">§resolved decisions <a class="header-anchor" href="#§resolved-decisions" aria-label="Permalink to &quot;§resolved decisions&quot;">​</a></h2><p><em>Resolved 2026-05-19 in scoping conversation with Marko.</em></p><ol><li><strong>Surface placement — RESOLVED: Banner on <code>/missions</code> + dedicated <code>/missions/launches</code> route.</strong> Two-tier surfacing.</li><li><strong>Data sourcing model — RESOLVED: Agency-first multi-source pipeline, LL2 as augmentation only.</strong> Direct sources: NASA / ESA / JAXA / SpaceX / Roscosmos / ISRO / CNSA (manual/scraping/RSS depending on what each agency exposes) + <strong>GCAT direct as the historic primary</strong> (the same source LL2 itself uses, bypassing LL2 in the historic chain entirely). LL2 fills upcoming-launch gaps the agency layer can&#39;t reach (small commercial, CubeSat, rideshare). Mirrors ADR-046 (agency-first imagery) and ADR-051 (agency-first LEARN links).</li><li><strong>Historic register included — RESOLVED: YES, via GCAT direct.</strong></li><li><strong>Importance tiering — RESOLVED: Heuristic + curated override</strong> (<code>launches-curation.json</code>). Same auto + override pattern PRD-018&#39;s image-curation is moving toward.</li><li><strong>Calendar UI — RESOLVED: Hybrid timeline + month strip.</strong> Mobile-first at 375 px.</li><li><strong>Cross-integration scope (v0.1) — RESOLVED: Fleet launcher pages get &quot;next flight&quot; + &quot;recent flights&quot; widgets.</strong> Mission-catalogue backlinks best-effort.</li><li><strong>Refresh model — RESOLVED: Per-source cadence.</strong> GCAT weekly (its update cadence is ~monthly); LL2 augmentation every 6 h; agency-direct manual v0.1 → graduating to automated where APIs/RSS support it in v0.2.</li><li><strong>Attribution — RESOLVED: McDowell / GCAT citation surfaces on the calendar page itself, <code>/credits</code>, AND <code>/library</code>.</strong> CC-BY compliance is a ship-gate, enforced by <code>validate-data.ts</code>; not a follow-up. Each calendar row exposes a per-row provenance chip showing the chain.</li><li><strong>Editorial overlay — RESOLVED: T1 featured launches optionally carry an Orrery-authored one-sentence <code>editorial_note</code></strong> flowed through from the curation file. Pulls the calendar closer to the hand-curated catalogue&#39;s editorial voice without forcing an Orrery write-up on every routine commercial launch.</li><li><strong>i18n strategy — RESOLVED: UI chrome via Paraglide, source-data English-only v0.1.</strong></li></ol><hr><h2 id="§open-questions" tabindex="-1">§open questions <a class="header-anchor" href="#§open-questions" aria-label="Permalink to &quot;§open questions&quot;">​</a></h2><ol><li><strong>Realistic agency-direct provider list for v0.1.</strong> Which agencies do we attempt direct integration with in the first slice? Recommend: NASA (RSS + KSC media schedule) + SpaceX (their upcoming-launches page) + ESA (press calendar) for v0.1; JAXA + Roscosmos + ISRO + CNSA fall back to GCAT (historic) + LL2 (upcoming) v0.1, with agency-direct added incrementally. RFC-023 to lock the v0.1 list.</li><li><strong>GCAT data shape vs. our schema.</strong> GCAT&#39;s Orbital Launch Log is the closest match. Verify at implementation time that the column set covers our M5 required fields without significant transformation. Likely yes (LL2 maps from GCAT for these fields already), but confirm.</li><li><strong>GCAT release-version pinning.</strong> Lock to a specific release (e.g. 1.8.0) per build. Bumping is operator-triggered, with a manual review pass on the schema diff. Avoids silent regressions if a future GCAT release adds/removes columns.</li><li><strong>Historic manifest paging granularity.</strong> Per-decade (~7 files, ~1 MB each) vs. per-year (~70 files, ~100 KB each). Per-decade probably wins. RFC-023.</li><li><strong><code>launches-rocket-mapping.json</code> seed.</strong> Manual mapping for our 23 fleet launchers + provision for &quot;per-config vs per-family&quot; matches. Recommend per-family default with optional per-config exception list.</li><li><strong>Agency-direct provider implementation cost.</strong> Most agencies don&#39;t expose JSON APIs — providers will be HTML scraping or RSS parsing. Each provider is ~½–1 day of engineering + ongoing brittleness when an agency reshuffles their press page. Worth it because it&#39;s the ONLY thing that prevents the &quot;we&#39;re a UI for LL2&quot; outcome. RFC-023 to lock the per-provider implementation pattern + the brittleness-tolerance posture (degrade-gracefully to LL2 + log a warning when an agency scraper breaks).</li><li><strong>PRD-018 alignment.</strong> Marko has asked PRD-018&#39;s image-curation to adopt the same heuristic + override pattern as <code>launches-curation.json</code>. Captured as a follow-up task on this scoping session.</li><li><strong>Failure-data tone.</strong> GCAT records fatalities (Soyuz 1, Challenger, Columbia, etc.) factually. v0.1 surfaces the GCAT text verbatim with attribution. Revisit case-by-case if any specific row feels off-tone.</li><li><strong>Build-cron commit author + commit message conventions.</strong> GH Actions bot identity + diff format. RFC-023.</li><li><strong>Editorial-note bandwidth.</strong> How many <code>editorial_note</code> strings does Marko realistically maintain per quarter? Probably ≤ 10 for the FEATURED rotation. Manageable. Worth confirming so the field doesn&#39;t become a thing that&#39;s &quot;supposed to be filled in&quot; but never is.</li></ol><hr><p><em>PRD-020 · Orrery · Launches Calendar · Drafted 2026-05-19 · Closes-into-RFC-023</em></p>',68)])])}const p=t(i,[["render",s]]);export{g as __pageData,p as default};
